DA221 DA221_inst;


void DA221_i2c_evt_handler(app_i2c_evt_t * p_evt)
{

        const char *type_str = "UNKNOWN";
        switch (p_evt->type) {
            case APP_I2C_EVT_TX_CPLT: type_str = "TX_CPLT"; break;
            case APP_I2C_EVT_RX_DATA: type_str = "RX_DATA"; break;
            case APP_I2C_EVT_ERROR:   type_str = "ERROR"; break;
            default: type_str = "UNKNOWN_EVT"; break;
        }

        printf("DA221 I2C EVT: type=%s, addr7=0x%02X", type_str, p_evt->slave_addr >> 1);

        if (p_evt->type == APP_I2C_EVT_ERROR) {
            printf(", err=0x%08X", p_evt->data.error_code);
        } else if (p_evt->type == APP_I2C_EVT_TX_CPLT || p_evt->type == APP_I2C_EVT_RX_DATA) {
            printf(", size=%d", p_evt->data.size);
        }

        printf("\r\n");

}


void DA221_i2c_dma_init(DA221 * const me) {
    uint16_t ret;
    ret = app_i2c_init(me->cfg.i2c_param, DA221_i2c_evt_handler);
    if (ret != APP_DRV_SUCCESS) {
        printf("I2C init error: %d", ret);
    }else{
        printf("I2C init ok: %d", ret);
    }
    ret = app_i2c_dma_init(me->cfg.i2c_param);
    if (ret != APP_DRV_SUCCESS) {
        printf("I2C DMA init error: %d", ret);
    }else{
        printf("I2C DMA init ok: %d", ret);
    }
}


