void DA221_ctor(DA221 * const me,
    Da221WorkMode mode)
{

        // QP活动对象基类初始化，绑定顶层初始状态
        QActive_ctor(&me->super, Q_STATE_CAST(&DA221_initial));

        me->cfg.pwr_cfg  = da221_pwr_default_cfg;
        // 绑定本实例私有I2C参数，不再使用全局i2c_params
        me->cfg.i2c_param = &i2c_params;

        // 根据工作模式绑定对应寄存器配置表
        if (mode == DA221_MODE_FULL_SPEED)
        {
            me->cfg.reg_table = da221_full_speed_config_table;
            me->cfg.table_len = da221_full_speed_config_table_size;
        }
        else
        {
            me->cfg.reg_table = da221_low_power_motion_config_table;
            me->cfg.table_len = da221_low_power_motion_config_table_size;
        }

        // 清空配置运行上下文
        me->cfg.step_index = 0U;
        me->cfg.retry_count = 0U;
        me->cfg.i2c_tmr_id = 0U;
        me->cfg.chip_id_buf = 0U;
        me->cfg.init_complete_cb = NULL;

        // DMA收发缓存清零
        memset(me->data.i2c_tx_buf, 0, sizeof(me->data.i2c_tx_buf));
        memset(me->data.i2c_rx_buf, 0, sizeof(me->data.i2c_rx_buf));

        // 三轴加速度清零
        me->data.accel_x = 0;
        me->data.accel_y = 0;
        me->data.accel_z = 0;

}


void DA221_io_int_init(void) {
        app_gpiote_param_t param[1] ={
             APP_IO_TYPE_AON,
             APP_IO_PIN_7,
             APP_IO_MODE_IT_BOTH_EDGE,
             APP_IO_NOPULL,
             DA221_gpio_int_callback,
         };
        app_gpiote_init(param, 1);
}


void DA221_start_dma_collect(DA221 * const me) {

        if (g_dma_done == false) {
            // 上一次传输未完成，跳过本次
            return;
        }

        g_dma_done = false;

        uint16_t ret = app_i2c_dma_mem_read_async(
            me->cfg.i2c_param->id,
            TK_DA221_ADDR,
            0x02,          // 加速度寄存器起始地址
            I2C_MEMADD_SIZE_8BIT,
            accel_buf,
            6
        );

        if (ret != APP_DRV_SUCCESS) {
            printf("DMA read start error: %d\r\n", ret);
            g_dma_done = true;
        }

}


