void DA221_read_accel(DA221 * const me) {
    //DA221_start_dma_collect(me);
    uint8_t xyz_buf[6] = {0};
    uint16_t ret = app_i2c_mem_read_sync(
        TK_I2C0_ID,              // I2C 模块 ID
        TK_DA221_ADDR,           // 7-bit 从机地址
        0x02,                    // XYZ 起始寄存器地址
        I2C_MEMADD_SIZE_8BIT,    // 8-bit 寄存器地址
        xyz_buf,                 // 接收缓冲区
        6,                       // 读取 6 字节
        100                      // 超时 100ms
    );

    if (ret == APP_DRV_SUCCESS) {
        // 解析 xyz_buf[0]~xyz_buf[5] 为 X/Y/Z
            /* 解析 12-bit 有符号值 (little-endian: 低 4 位在 LSB, 高 8 位在 MSB) */
        int16_t x = (int16_t)((xyz_buf[1] << 4) | (xyz_buf[0] >> 4));
        int16_t y = (int16_t)((xyz_buf[3] << 4) | (xyz_buf[2] >> 4));
        int16_t z = (int16_t)((xyz_buf[5] << 4) | (xyz_buf[4] >> 4));

        /* 2's complement 符号扩展 (12-bit → 16-bit) */
        if (x > 2047) x -= 4096;
        if (y > 2047) y -= 4096;
        if (z > 2047) z -= 4096;

        printf(",X=%d,Y=%d,Z=%d\r\n", x, y, z);
    } else {
        printf("Read XYZ failed, ret=%d\r\n", ret);
    }
}


QState DA221_initial(DA221 * const me, void const * const par) {
    
    delay_ms(200);
    return Q_TRAN(&DA221_UNINIT);
}


QState DA221_UNINIT(DA221 * const me, QEvt const * const e) {
    QState status_;
    switch (e->sig) {
        
        case Q_ENTRY_SIG: {
            printf("--> sensor UNINIT");
             // 先初始化电源
             DA221_i2c_dma_init(me); // 替换为正确的I2C初始化函数
            // 检测传感器I2C应答
            uint8_t chip_id = 0;
            uint16_t ret = app_i2c_mem_read_sync(
                    TK_I2C0_ID,
                    TK_DA221_ADDR,
                    0x01,
                    I2C_MEMADD_SIZE_8BIT,
                    &chip_id,
                    1,
                    DA221_I2C_TIMEOUT_MS);

            if (ret == APP_DRV_SUCCESS && chip_id == DA221_CHIP_ID_VALID) {
                printf("Chip ID read OK: 0x%02X\r\n", chip_id);
                QACTIVE_POST(&me->super, Q_NEW(QEvt, DA221_INIT_OK_SIG), 0U);
            } else {
                printf("Chip ID read fail, ret=%d, id=0x%02X\r\n", ret, chip_id);
                QACTIVE_POST(&me->super, Q_NEW(QEvt, DA221_I2C_ERROR_SIG), 0U);
            }
            status_ = Q_HANDLED();
            break;
        }
        
        case Q_EXIT_SIG: {
            printf("sensor UNINIT -->");
            status_ = Q_HANDLED();
            break;
        }
        
        case DA221_INIT_OK_SIG: {
            status_ = Q_TRAN(&DA221_ACTIVE);
            break;
        }
        default: {
            status_ = Q_SUPER(&QHsm_top);
            break;
        }
    }
    return status_;
}


