QState DA221_CONFIG_BUSY(DA221 * const me, QEvt const * const e) {
    QState status_;
    switch (e->sig) {
        
        case Q_ENTRY_SIG: {
            const I2cRegCfg_t *cfg = &me->cfg.reg_table[me->cfg.step_index];
            me->data.i2c_tx_buf[0] = cfg->reg;
            me->data.i2c_tx_buf[1] = cfg->data;
            uint16_t ret = DA221_i2c_write(me, me->data.i2c_tx_buf, 2);

            delay_ms(1);
            if (ret != APP_DRV_SUCCESS) {
                QACTIVE_POST(&me->super, Q_NEW(QEvt, DA221_CFG_KO_SIG), 0U);
            } else {
                QACTIVE_POST(&me->super, Q_NEW(QEvt, DA221_CFG_OK_SIG), 0U);
            }

            printf("%s reg:[data=0x%02X:0x%02X]rty:[%d]critical:[%d] step[%d]",
                (ret != APP_DRV_SUCCESS) ? "KO !" : "OK !",cfg->reg, cfg->data,
                me->cfg.retry_count,me->cfg.reg_table[me->cfg.step_index].critical,me->cfg.step_index);

            status_ = Q_HANDLED();
            break;
        }
        
        case Q_EXIT_SIG: {
            //printf("sensor CONFIG_BUSY -->");
            status_ = Q_HANDLED();
            break;
        }
        
        case DA221_I2C_ERROR_SIG: // intentionally fall through
        case DA221_CFG_KO_SIG: {
            me->cfg.retry_count++;

            
            if (me->cfg.retry_count < MAX_RETRIES) {
                status_ = Q_TRAN(&DA221_CONFIG_BUSY);
            }
            
            else {
                
                if (me->cfg.reg_table[me->cfg.step_index].critical == true) {
                    me->cfg.step_index = 0U;
                    me->cfg.retry_count = 0U;
                    status_ = Q_TRAN(&DA221_CONFIG_BUSY);
                }
                
                else {
                    printf("[DA221] Non-critical reg 0x%02X config fail, skip",
                                     me->cfg.reg_table[me->cfg.step_index].reg);
                    me->cfg.step_index++;
                    status_ = Q_TRAN(&DA221_CONFIG_BUSY);
                }
            }
            break;
        }
        
        case DA221_I2C_TX_DONE_SIG: // intentionally fall through
        case DA221_CFG_OK_SIG: {
            me->cfg.step_index++;
            me->cfg.retry_count = 0;
            
            if (me->cfg.step_index < me->cfg.table_len) {
                status_ = Q_TRAN(&DA221_CONFIG_BUSY);
            }
            
            else {
                if (me->cfg.init_complete_cb != NULL) {
                    me->cfg.init_complete_cb(true); // 回调通知成功
                }
                printf("[DA221] Config done\r\n");
                DA221_io_int_init();
                status_ = Q_TRAN(&DA221_IDLE);
            }
            break;
        }
        default: {
            status_ = Q_SUPER(&DA221_ACTIVE);
            break;
        }
    }
    return status_;
}
